<?php use App\Support\App;App::requireAdmin();$rows=App::db()->query('SELECT * FROM products ORDER BY sort_order,id DESC')->fetchAll();$title='Products';require __DIR__.'/../layouts/head.php';?><main class="p-8 max-w-6xl mx-auto"><h1 class="text-2xl font-semibold">Products</h1><button class="btn btn-dark mt-4" onclick="imp()">Import CeirGo</button><div class="saas-card p-5 mt-5 overflow-auto"><table class="w-full"><?php foreach($rows as $p):?><tr class="border-b"><td class="p-3"><?=htmlspecialchars($p['name'])?></td><td><?=$p['provider_type']?></td><td><?=$p['is_active']?'ON':'OFF'?></td></tr><?php endforeach?></table></div></main><script>async function imp(){let r=await fetch('/api/admin/products/import-ceirgo',{method:'POST',headers:{'X-CSRF-Token':'<?=App::csrf()?>'}});Swal.fire(JSON.stringify(await r.json()))}</script><?php require __DIR__.'/../layouts/foot.php';?>